export function companionError(language:Language,error:unknown):string{
 const message=error instanceof Error?error.message:typeof error==='string'?error:'';
 const key=companionErrorKeys[message]??(Object.prototype.hasOwnProperty.call(companionTranslationRows,message)?message as CompanionMessageKey:undefined);
 if(key)return translateCompanion(language,key);
 if(message.startsWith('mission_requirement_'))return translateCompanion(language,'The selected team does not meet every assignment requirement.');
 if(message.startsWith('missing_material:')||/^Missing .*material/i.test(message))return translateCompanion(language,'Missing companion materials.');
 if(message.startsWith('Cannot equip:'))return translateCompanion(language,'Same role as your character');
 const bond=/^Reach Bond (\d+) first\.$/.exec(message);
 if(bond)return translateCompanion(language,'Reach Bond {level} first.',{level:bond[1]});
 return translateCompanion(language,'Unable to complete action.');
}

export function companionAttentionText(language:Language,summary:{expeditionClaims:number;bondRewards:number;ascensions:number;sanctuaryClaims:number;codexClaims:number;monthlyTrialClaims:number;recentUnlocks:number}){
 const counts:[CompanionMessageKey,number][]=[
  ['Expeditions ready: {count}',summary.expeditionClaims],['Bond rewards: {count}',summary.bondRewards],
  ['Ascensions ready: {count}',summary.ascensions],['Sanctuary claims: {count}',summary.sanctuaryClaims],
  ['Codex rewards: {count}',summary.codexClaims],['Trial rewards: {count}',summary.monthlyTrialClaims],
  ['New companions: {count}',summary.recentUnlocks],
 ];
 return counts.filter(([,count])=>count>0).map(([key,count])=>translateCompanion(language,key,{count}));
}

/** Canonical progress messages remain unchanged in state so language switches are immediate. */
export function companionMessage(language:Language,message:string):string{
 const t=companionTranslator(language);
 const divider=message.indexOf(' · ');
 if(divider>=0&&['TRAINING COMPLETE','ASCENSION COMPLETE','PRESTIGE MASTERY COMPLETE','BOND REWARD CLAIMED','TECHNIQUE UPDATED','NEW COMPANION'].includes(message.slice(0,divider))){
  return companionLabel(language,message.slice(0,divider))+' · '+companionMessage(language,message.slice(divider+3));
 }
 let match=/^(.*) reached Level (\d+)\.$/.exec(message);
 if(match)return t('{name} reached Level {level}.',{name:match[1],level:match[2]});
 match=/^(.*) reached Tier (\d+)\.(?: Level cap (\d+) is now available\.)?$/.exec(message);
 if(match)return t('{name} reached Tier {tier}.',{name:match[1],tier:match[2]})+(match[3]?' '+t('Level cap {cap} is now available.',{cap:match[3]}):'');
 match=/^(.*) reached its final mastery milestone\.$/.exec(message);
 if(match)return t('{name} reached its final mastery milestone.',{name:match[1]});
 match=/^(.*?)(?:'s)? combat choice is ready\.$/.exec(message);
 if(match)return t("{name}'s combat choice is ready.",{name:match[1]});
 match=/^(.*) · Bond (\d+) · (.*)\.$/.exec(message);
 if(match)return t('{name} · Bond {level} · {reward}.',{name:match[1],level:match[2],reward:companionLabel(language,match[3])});
 const content=companionContent(language,message);
 return content!==message||Object.prototype.hasOwnProperty.call(companionTranslationRows,message)?content:companionError(language,message);
}

export const companionContentTemplates=["Rare drop from {name}","Rare discovery while mining {name}","Rare discovery while cutting {name}","Rare discovery while fishing {name}","Rare discovery while gathering {name}","{chance}% drop from {name}","Reach character level {level}","Reach {name} Mastery {level}","Complete {count} {region} Sanctuary assignments","Earn S grade on {count} {region} Sanctuary assignments","Raise {name} to Bond {level}","Defeat the {name} companion challenge","Earn {name} from {event}.","Own {name}.","Hunt {name}","Craft {name}","Gather at {name}","{region} · {chance} drop chance","Ascend to Tier {tier}","Train to Level {level}","Raise Bond to {level}","Bond {level}","Ascension {tier}","Reach Level {level}, then Ascend","Level cap {level}"] as const satisfies readonly CompanionMessageKey[];
const contentPatterns=companionContentTemplates.map(key=>{
 const names:string[]=[];
 const escaped=key.replace(/[.*+?^$()|[\]\\]/g,'\\$&').replace(/\{([a-zA-Z][a-zA-Z0-9_]*)\}/g,(_,name:string)=>{names.push(name);return '(.+?)';});
 return {key,names,pattern:new RegExp('^'+escaped+'$')};
});
/** Translate only authored description fields. Interpolated names remain untouched. */
export function companionUnlockRequirement(language:Language,requirement:string):string{
 if(requirement.startsWith('Complete '))return translateCompanion(language,'Complete {quest}',{quest:requirement.slice('Complete '.length)});
 return companionContent(language,requirement);
}

export function companionContent(language:Language,value:string):string{
 if(Object.prototype.hasOwnProperty.call(companionTranslationRows,value))return translateCompanion(language,value as CompanionMessageKey);
 for(const {key,names,pattern} of contentPatterns){
  const match=pattern.exec(value);
  if(match)return translateCompanion(language,key,Object.fromEntries(names.map((name,index)=>[name,match[index+1]])));
 }
 return companionLabel(language,value);
}

